// F57 Barkens rad i migrationsfilen. Varje supabase/*.sql börjar med
//   rad 1: "-- Barken: <Namn>, <ÅÅÅÅ-MM-DD>" eller "-- Barken: inte läst"
//   rad 2: "-- Körd: <ÅÅÅÅ-MM-DD>", "-- Körd: nej" eller "-- Körd: före F57" (bara 001 och 003).
// En körd fil måste vara läst av Barken, och läsningen får inte ligga efter körningen.
// Testet läser bara filer i supabase/ och kör social-posts-testet; inget nätverk, inga hemligheter.
// AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const FORE_F57_TILLATET = ['001_initial.sql', '003_post_taggar.sql'];
const RAD1 = /^-- Barken: (?:inte läst|(\p{Lu}[\p{L}'-]*(?: \p{L}[\p{L}'-]*)*), (\d{4}-\d{2}-\d{2}))$/u;
const RAD2 = /^-- Körd: (?:nej|före F57|(\d{4}-\d{2}-\d{2}))$/u;

function idag() {
  const d = new Date();
  return new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate())).toISOString().slice(0, 10);
}
function giltigt(s) {
  const d = new Date(s + 'T00:00:00Z');
  return !isNaN(d) && d.toISOString().slice(0, 10) === s;
}

// Kontrollerar en fils text; returnerar { fel: [...], inteLast: bool }.
function kontrollera(namn, text, dagens = idag()) {
  const fel = [];
  const rader = text.split(/\r?\n/);
  const m1 = RAD1.exec(rader[0] || '');
  const m2 = RAD2.exec(rader[1] || '');
  if (!m1) fel.push(`${namn}: rad 1 är inte "-- Barken: <Namn>, <datum>" eller "-- Barken: inte läst"`);
  if (!m2) fel.push(`${namn}: rad 2 är inte "-- Körd: <datum>", "-- Körd: nej" eller "-- Körd: före F57"`);
  if (!m1 || !m2) return { fel, inteLast: !!(rader[0] || '').match(/^-- Barken: inte läst$/) };
  const inteLast = !m1[1];
  const lastDatum = m1[2];
  const kordDatum = m2[1];
  const foreF57 = rader[1] === '-- Körd: före F57';
  for (const [vad, dat] of [['Barkens datum', lastDatum], ['körddatum', kordDatum]]) {
    if (!dat) continue;
    if (!giltigt(dat)) fel.push(`${namn}: ${vad} ${dat} är inget giltigt datum`);
    else if (dat > dagens) fel.push(`${namn}: ${vad} ${dat} ligger i framtiden`);
  }
  if (kordDatum && inteLast) fel.push(`${namn}: körd ${kordDatum} utan Barkens läsning`);
  if (kordDatum && lastDatum && lastDatum > kordDatum) fel.push(`${namn}: Barken läste ${lastDatum}, efter körningen ${kordDatum}`);
  if (foreF57 && !FORE_F57_TILLATET.includes(namn)) fel.push(`${namn}: "före F57" gäller bara ${FORE_F57_TILLATET.join(' och ')}`);
  return { fel, inteLast };
}

// 1–3. Filerna i supabase/.
const dir = 'supabase';
const filer = fs.existsSync(dir) ? fs.readdirSync(dir).filter((f) => f.endsWith('.sql')).sort() : [];
const fel = [];
const inteLasta = [];
for (const f of filer) {
  const r = kontrollera(f, fs.readFileSync(path.join(dir, f), 'utf8'));
  fel.push(...r.fel);
  if (r.inteLast) inteLasta.push(f);
}
const filerFinns = filer.length >= 3;
if (!filerFinns) fel.push(`supabase/ har ${filer.length} .sql-filer, minst 3 krävs`);
const allaHarRaderna = filerFinns && fel.length === 0;

// 4. Självprov på sju strängar.
const prov = [
  ['ny.sql', '-- Körd: nej\n-- Barken: inte läst\n', true],                       // fel ordning
  ['ny.sql', '-- Barken: inte läst\n-- Körd: 2026-11-20\n', true],                 // körd men oläst
  ['ny.sql', '-- Barken: Amina Diallo, 2026-11-21\n-- Körd: 2026-11-20\n', true],  // läst efter körning
  ['ny.sql', '-- Barken: inte läst\n-- Körd: före F57\n', true],                   // före F57 på ny fil
  ['ny.sql', '-- Barken: Bjarke, 2999-01-01\n-- Körd: nej\n', true],               // framtida datum
  ['ny.sql', '-- Barken: Amina Diallo, 2026-11-19\n-- Körd: 2026-11-20\n', false], // läst före körning
  ['ny.sql', '-- Barken: inte läst\n-- Körd: nej\n', false],                       // oläst och okörd
];
const provFel = prov.filter(([n, t, borFela]) => (kontrollera(n, t, '2026-11-22').fel.length > 0) !== borFela);
const testetFangar = provFel.length === 0;
if (!testetFangar) fel.push(`självprovet: ${provFel.length} av 7 strängar gav fel utfall`);

// 5. social-posts-testet är fortfarande grönt.
const sp = spawnSync(process.execPath, [path.join('tests', 'social-posts.test.cjs')], { encoding: 'utf8' });
const socialPostsGront = sp.status === 0;
if (!socialPostsGront) fel.push('tests/social-posts.test.cjs är rött');

const ok = filerFinns && allaHarRaderna && testetFangar && socialPostsGront;
if (!ok) console.error(fel.join('\n'));
console.log(JSON.stringify({ filer, fel, inteLasta, filerFinns, allaHarRaderna, testetFangar, socialPostsGront, ok }));
process.exit(ok ? 0 : 1);
